 endforeach;?></select></label><div class="two-fields"><label>Focal point X (%)<input type="number" name="focal_x" min="0" max="100" step="0.1" value="<?= e($asset['focal_x']) ?>"></label><label>Focal point Y (%)<input type="number" name="focal_y" min="0" max="100" step="0.1" value="<?= e($asset['focal_y']) ?>"></label></div><button class="button secondary small" type="submit">Save details</button></form><div class="media-usage-panel"><strong>Usage</strong><?php if($refs):?><ul><?php foreach($refs as $ref):?><li><a href="<?= e($ref['url']) ?>"><?= e($ref['kind'].' · '.$ref['label']) ?></a></li><?php endforeach;?></ul><?php else:?><p class="field-help">No direct structured-content or SEO references found.</p><?php endif;?></div><div class="media-transform-panel"><strong>Quick image edits</strong><p class="field-help">Edits the stable library asset. Focal point guides crops; responsive variants regenerate automatically.</p><div class="media-transform-actions"><?php foreach(['rotate_left'=>'Rotate left','rotate_right'=>'Rotate right','crop_square'=>'Crop 1:1','crop_4_3'=>'Crop 4:3','crop_16_9'=>'Crop 16:9'] as $operation=>$label):?><form method="post" action="<?= e(admin_url('/media/'.(int)$asset['id'].'/transform')) ?>"><?= Csrf::field() ?><input type="hidden" name="operation" value="<?= e($operation) ?>"><button class="button secondary small" type="submit"><?= e($label) ?></button></form><?php endforeach;?></div></div><form method="post" action="<?= e(admin_url('/media/'.(int)$asset['id'].'/replace')) ?>" enctype="multipart/form-data" class="media-replace-form"><?= Csrf::field() ?><label>Replace image file<input type="file" name="replacement" accept="image/jpeg,image/png,image/webp,.jpg,.jpeg,.png,.webp" required><small class="field-help">Keeps Media ID #<?= (int)$asset['id'] ?> and all stable references.</small></label><button class="button secondary small" type="submit">Replace file</button></form><form method="post" action="<?= e(admin_url('/media/'.(int)$asset['id'].'/delete')) ?>" class="media-delete-form"><?= Csrf::field() ?><label class="confirm-check"><input type="checkbox" name="confirm_delete" value="1" required> Confirm permanent deletion</label><button class="text-button danger-text" type="submit">Delete media</button></form></div></details><?php endif;?></div></div></article><?php endforeach;?></div><?php endif;?>
